def swap_extreme_regions(src, r_start, r_end, dest, num_cols=23):
    """Swap content between leftmost and rightmost non-empty regions"""
    # Define region boundaries (skip dividers at 5, 11, 17)
    regions = []
    cur = 0
    while cur < num_cols:
        if cur < 5: regions.append((cur, 4))
        elif cur == 5: cur = 6
        elif cur < 11: cur += 1
        elif cur == 11: cur = 12
        elif cur < 17: cur += 1
        elif cur == 17: cur = 18
        else: regions.append((cur, cur))
        cur += 1

    # Find actual non-empty regions
    def find_content(start, end):
        for r in range(r_start, r_end):
            for c in range(start, end + 1):
                v = src[r][c]
                if v != 0 and v != 8:
                    return start, end
        return None, None

    reg_left, reg_right = find_content(*regions[0], *regions[-1])

    if reg_left is None or reg_right is None:
        # No content to swap, just copy everything
        for r in range(r_start, r_end):
            for c in range(num_cols):
                if src[r][c] != 0 and src[r][c] != 8:
                    dest[r][c] = src[r][c]
        return

    # Copy other regions as-is
    for i, (rs, re) in enumerate(regions[1:-1]):
        if rs is not None:
            for r in range(r_start, r_end):
                for c in range(rs, re + 1):
                    if src[r][c] != 0 and src[r][c] != 8:
                        dest[r][c] = src[r][c]

    # Swap leftmost and rightmost
    if reg_left is not None and reg_right is not None:
        for r in range(r_start, r_end):
            for c in range(reg_left[0], reg_left[1] + 1):
                v = src[r][c]
                if v != 0 and v != 8:
                    dest[r][c + reg_right[0] - reg_left[0]] = v
            for c in range(reg_right[0], reg_right[1] + 1):
                v = src[r][c]
                if v != 0 and v != 8:
                    dest[r][c - reg_right[0] + reg_left[0]] = v

